{"step":1,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_init)","line":1540,"var":"arg_str","code":"ZVAL_STR_COPY(&MBREX(search_str), arg_str);","note":"The attacker initializes the global search subject with a string that contains the target pattern."},
{"step":2,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_init)","line":1551,"var":"MBREX(search_re)","code":"if (argc > 1) { MBREX(search_re) = php_mbregex_compile_pattern(arg_pattern, arg_pattern_len, option, MBREX(current_mbctype), syntax); }","note":"The caller also supplies the pattern that becomes the persistent search regex object."},
{"step":3,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_regs)","line":1592,"var":"MBREX(search_re)","code":"if (MBREX(search_regs) != NULL && Z_TYPE(MBREX(search_str)) == IS_STRING) { ... onig_foreach_name(MBREX(search_re), mb_regex_groups_iter, &args); }","note":"The first search-regs call consumes the initialized global state and walks the named-group list in the compiled regex object."},
{"step":4,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_eregi_replace)","line":1224,"var":"pattern","code":"re = php_mbregex_compile_pattern(pattern, pattern_len, options, enc, syntax);","note":"A second API compiles the same textual pattern family and exercises the shared regex cache from another code path."},
{"step":5,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"php_mbregex_compile_pattern","line":470,"var":"MBREX(search_re)","code":"if (rc == MBREX(search_re)) { /* reuse the new rc? see bug #72399 */ MBREX(search_re) = NULL; }","note":"If the cache returns the same compiled object, the global search_re pointer is nulled, leaving later uses with a stale alias hazard."},
{"step":6,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_pos)","line":1438,"var":"MBREX(search_re)","code":"err = _php_mb_onig_search(MBREX(search_re), str, str + len, str + pos, str + len, MBREX(search_regs), 0);","note":"The final search-position call dereferences the global regex pointer after the cache interaction, reaching the suspected use-after-free read."}
]
EOF

